const chunking = {
  chunkingStrategy: 'HIERARCHICAL',
  hierarchicalChunkingConfiguration: {
    levelConfigurations: [
      { maxTokens: 1500 },
      { maxTokens: 300 },
    ],
    overlapTokens: 60,
