steps.infrastructure:
// Chunking is locked at data-source creation. Hierarchical keeps a section
// attached to its heading, which a leave policy needs: a clause split from
// 'applies in Germany' is not an answer. Changing this later is a new data
// source and a re-ingest, so the strategy is chosen before the corpus loads.
const chunking = {
  chunkingStrategy: 'HIERARCHICAL',
  hierarchicalChunkingConfiguration: {
    levelConfigurations: [{ maxTokens: 1500 }, { maxTokens: 300 }],
    overlapTokens: 60,
  },
};

