steps.infrastructure:
// The embedding model and the index dimension are one decision. Titan v2
// writes 1024-wide vectors; the index field is 1024. A different model
// writes a different width the index cannot search, and switching later is
// a full rebuild, not a setting. So they are declared together.
const EMBED_MODEL = 'amazon.titan-embed-text-v2:0';
const EMBED_DIM = 1024;

