# policy.pdf.metadata.json, beside policy.pdf in the corpus bucket
{
  "metadataAttributes": {
    "department": "hr",
    "effective_date": "2026-01-01",
    "classification": "internal"
  }
}

found = agent.retrieve(
    knowledgeBaseId="KB1234567890",
    retrievalQuery={"text": QUESTION},
    retrievalConfiguration={
        "vectorSearchConfiguration": {
            "filter": {"equals": {"key": "department", "value": "hr"}}
        }
    },
)

for chunk in found["retrievalResults"]:
    dept = chunk["metadata"]["department"]
    uri = chunk["location"]["s3Location"]["uri"]
    print(f"[{dept}] {uri}")
    print(chunk["content"]["text"])

steps.infrastructure:
// The department lives in a sidecar beside each object, ingested as a
// filterable attribute. Isolation is this filter plus IAM, never a prompt
// instruction: 'only use HR docs' arrives after the other chunks are
// already in context. The same key is on every object, or a missing key
// drops the document without an error.

// Event-driven ingest: an object lands, a job starts. A nightly or weekly
// full rebuild serves this morning's superseded policy until it finishes.
// The deletion policy removes vectors for deleted objects, because a
// retained vector keeps a withdrawn policy citable — the stale-answer
// failure again.
corpus.addEventNotification(
  EventType.OBJECT_CREATED,
  new LambdaDestination(startIngestFn),
);

