import boto3

agent = boto3.client("bedrock-agent-runtime", region_name="eu-central-1")

out = agent.retrieve_and_generate(
    input={"text": "How many weeks of parental leave apply in Germany?"},
    retrieveAndGenerateConfiguration={
        "type": "KNOWLEDGE_BASE",
        "knowledgeBaseConfiguration": {
            "knowledgeBaseId": "KB1234567890",
            "modelArn": "eu.anthropic.claude-sonnet-4-5-20250929-v1:0",
        },
    },
)

print(out["output"]["text"])

for citation in out["citations"]:
    for ref in citation["retrievedReferences"]:
        print(ref["location"]["s3Location"]["uri"])

steps.infrastructure:
// RetrieveAndGenerate needs no new infrastructure beyond the knowledge base
// and the model access already provisioned. The citation array it returns is
// what makes the answer actionable: a file name the employee can open, not a
// paraphrase they have to trust.

