const guardrail = new CfnGuardrail(this, 'PolicyGuardrail', {
  name: 'policy-assistant',
  contextualGroundingPolicyConfig: {
    filtersConfig: [
      { type: 'GROUNDING', threshold: 0.7 },
      { type: 'RELEVANCE', threshold: 0.7 },
    ],
  },
  contentPolicyConfig: {
    filtersConfig: [{ type: 'PROMPT_ATTACK', inputStrength: 'HIGH', outputStrength: 'NONE' }],
  },
});

const version = new CfnGuardrailVersion(this, 'PolicyGuardrailV1', {
  guardrailIdentifier: guardrail.attrGuardrailId,
  description: 'grounding + prompt-attack, policy assistant',
});

steps.infrastructure:
// Grounding checks the answer is supported by the retrieved sources;
// prompt-attack runs on those sources because indirect injection hides in a
// chunk. Production pins a numbered version: DRAFT is mutable and a mid-edit
// change would hit a live workload. A version is created after every edit.

