// private subnet does not. The endpoint policy is part of the design.
const bedrockEndpoint = vpc.addInterfaceEndpoint('BedrockRuntime', {
  service: InterfaceVpcEndpointAwsService.BEDROCK_RUNTIME,
  subnets: { subnetType: SubnetType.PRIVATE_WITH_EGRESS },
});

