const prompt = new CfnPrompt(this, 'PolicyPrompt', {
  name: 'policy-answer',
  variants: [{
    name: 'v1',
    templateType: 'TEXT',
    templateConfiguration: {
      text: { text: 'Answer only from the sources. Cite the file. {{context}} Question: {{question}}' },
    },
  }],
});

const promptVersion = new CfnPromptVersion(this, 'PolicyPromptV1', {
  promptArn: prompt.attrArn,
  description: 'cite-the-file answer prompt, v1',
});

steps.infrastructure:
// The prompt is a managed template with versions, referenced by id. A
// string edited in the Lambda hides who changed the words and couples the
// prompt to a code rollback. A 'no change' deploy that silently moved the
// prompt is a known cause of an unexplained quality drop — versioning is
// what makes that reviewable.
const prompt = new CfnPrompt(this, 'PolicyPrompt', { name: 'policy-answer', variants: [promptVariant] });

